//! Each game's hook points by their permanent ids (docs/port/MODS.md, section 4): a manifest may
//! name a hook point by its id (`rac1.player.turn_to_heading`) or by its name
//! (`Hero_TurnToHeading`), and two mods that name it either way share it. The table is generated by
//! sdk/tools/gen_binding.py (`hook_ids.json`, beside this file) and built in, since an installed
//! launcher has no copy of the port's.

use std::collections::HashMap;
use std::sync::OnceLock;

fn table() -> &'static HashMap<String, HashMap<String, String>> {
    static TABLE: OnceLock<HashMap<String, HashMap<String, String>>> = OnceLock::new();
    TABLE.get_or_init(|| {
        let v: serde_json::Value = serde_json::from_str(include_str!("hook_ids.json")).unwrap_or_default();
        let mut out = HashMap::new();
        if let Some(games) = v.get("games").and_then(|g| g.as_object()) {
            for (game, names) in games {
                let names = names
                    .as_object()
                    .map(|m| m.iter().filter_map(|(k, v)| Some((k.clone(), v.as_str()?.to_string()))).collect())
                    .unwrap_or_default();
                out.insert(game.clone(), names);
            }
        }
        out
    })
}

/// The id `name` stands for in `game`: itself when it is an id, or a name the table does not have.
pub fn id<'a>(game: &str, name: &'a str) -> std::borrow::Cow<'a, str> {
    match table().get(game).and_then(|names| names.get(name)) {
        Some(id) => std::borrow::Cow::Owned(id.clone()),
        None => std::borrow::Cow::Borrowed(name),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn names_and_ids_are_one_hook_point() {
        assert_eq!(id("rac1", "Hero_TurnToHeading"), "rac1.player.turn_to_heading");
        assert_eq!(id("rac1", "rac1.player.turn_to_heading"), "rac1.player.turn_to_heading");
        assert_eq!(id("rac1", "Moby_Bolt_Update"), "rac1.moby.bolt.update");
        assert_eq!(id("rac1", "Not_A_Hook"), "Not_A_Hook");
        assert_eq!(id("rac2", "Hero_TurnToHeading"), "Hero_TurnToHeading");
    }
}
